for (const key in automatedShifts) {
  const values = automatedShifts[key];

  //check if the key already exists in semanticDriftRules
  if (Object.hasOwn(semanticDriftRules, key)) {
    //if the key already exists, merge the two arrays
    values.forEach((value) => {
      console.log("merging values")
      //only if the given semantic shift is not already listed in semanticDriftRules
      if (!semanticDriftRules[key].includes(value)) {
        semanticDriftRules[key].push(value);
      }
    });
  } else {
    //semanticDriftRules does not already have key, so add it
    values.forEach((value) => {
      semanticDriftRules[key] = value;
      console.log("added key")
    });
    
  }
}

//now add the merged array to a .txt file, copy and paste to replace the semanticDriftRules object in semanticShift.jsx
fs.writeFileSync(
  "mergedSemanticShifts.txt",
  JSON.stringify(semanticDriftRules, null, 2),
  "utf8"
);
